 if(!close){canvas.style.display='none';densityCanvas.style.display='none';document.getElementById('map-mode').textContent='UP TO '+fmt(targetGroupSize(map.getZoom(),Number($('#density').value)))+' VOTES PER GROUP';document.getElementById('map-message').textContent='One party per group · grey: groups share a pixel';if(ready){let id=request;timer=setTimeout(()=>worker.postMessage({type:'render',id,selected:active,zoom:map.getZoom(),density:Number($('#density').value),view:{x:b.x,y:b.y,width:size.x,height:size.y,world:256*2**map.getZoom()}}),90)}return}
