function winner(feature){return Object.entries(feature.properties.votes).reduce((best,current)=>current[1]>best[1]?current:best)[0]}
function updateRidingStyles(){if(!boundary)return;const key=chosenName;if(lastStyleKey===key)return;lastStyleKey=key;boundary.setStyle(feature=>({color:feature.properties.name===chosenName?'#233d34':'#789688',weight:feature.properties.name===chosenName?2:0.8,opacity:0.68,fillColor:'#c5d9ca',fillOpacity:0}))}
function legend(){let order=['Conservative Party','BC NDP','BC Green Party',...meta.parties.filter(x=>!['Conservative Party','BC NDP','BC Green Party'].includes(x))];$('#legend').innerHTML='';for(let p of order){let b=document.createElement('button');b.classList.toggle('dim',active>=0&&active!==meta.parties.indexOf(p));b.innerHTML=`<span class="swatch" style="background:${palette[p]}"></span>${p}`;b.onclick=()=>{let id=meta.parties.indexOf(p);active=active===id?-1:id;legend();render()};$('#legend').append(b)}}
function choose(feature,fly=true){if(!feature){select.value='';chosenName='';updateRidingStyles();$('#detail').innerHTML='<div class="detail-label">THE BIG PICTURE</div><h2>British Columbia</h2><p>Select a riding on the map or from the list to see its results.</p>';if(fly)map.setView([54.8,-125],5);return}let p=feature.properties;select.value=p.name;chosenName=p.name;updateRidingStyles();boundary.eachLayer(l=>{if(l.feature.properties.name===p.name&&fly)map.fitBounds(l.getBounds(),{padding:[45,45],maxZoom:12})});let rows=Object.entries(p.votes).sort((a,b)=>b[1]-a[1]).map(([party,votes])=>`<div class="result-row"><span><i class="swatch" style="display:inline-block;background:${palette[party]}"></i> ${party}</span><b>${fmt(votes)}</b></div>`).join('');$('#detail').innerHTML=`<div class="detail-label">RIDING RESULTS</div><h2>${p.name}</h2><p>${fmt(p.total)} valid votes · ${fmt(p.area)} km²</p>${rows}`}
Promise.all([fetch('riding-ids.gz').then(r=>{if(!r.ok)throw Error('Riding data could not be loaded');return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer()}),fetch('meta.json').then(r=>r.json()),fetch('ridings.json').then(r=>r.json()),Promise.all(Array.from({length:8},(_,i)=>fetch('votes-'+String(i).padStart(2,'0')+'.gz').then(r=>{if(!r.ok)throw Error('Vote data could not be loaded');return r.arrayBuffer()}))).then(parts=>new Response(new Blob(parts).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())]).then(([ids,m,g,b])=>{meta=m;let districts=g.features.map(f=>({name:f.properties.name,total:f.properties.total,counts:meta.parties.map(p=>f.properties.votes[p]||0)}));features=[...g.features];$('#voteTotal').textContent=(m.total/1e6).toFixed(2)+'M';if(b.byteLength/12!==m.total||ids.byteLength!==m.total)throw Error('Vote data does not match totals.');boundary=L.geoJSON(g,{style:{color:'#789688',weight:.8,opacity:.68,fillColor:'#c5d9ca',fillOpacity:0},onEachFeature:(f,l)=>l.on('click',()=>choose(f))}).addTo(map);features.sort((a,b)=>a.properties.name.localeCompare(b.properties.name));for(let f of features){let o=document.createElement('option');o.value=f.properties.name;o.textContent=f.properties.name;select.append(o)}select.onchange=()=>choose(features.find(f=>f.properties.name===select.value));$('#reset').onclick=()=>choose(null);$('#showAll').onclick=()=>{active=-1;legend();render()};$('#density').onchange=()=>render();legend();setupGL(b,ids,districts);loading.remove()}).catch(e=>{console.error(e);loading.textContent='The map could not load: '+e.message});
